const fs = require('node:fs');
const assert = require('node:assert/strict');
const { PGlite } = require('@electric-sql/pglite');
const read = name => fs.readFileSync(`supabase/migrations/${name}`, 'utf8');

(async () => {
  const db = new PGlite();
  try {
    await db.exec('create role anon; create role authenticated; create role service_role bypassrls;');
    await db.exec(read('20261029043118_marketing_leads_foundation.sql'));
    // This is the SQL shape generated by the deployed webhook's upsert options.
    const insert = `insert into public.marketing_leads(leadgen_id,full_name,status,notes)
      values ($1,$2,'new',null) on conflict (leadgen_id) do nothing returning id`;
    await assert.rejects(db.query(insert, ['meta-1', 'Fixture']), error => error.code === '42P10');
    const migration = read('20261030035952_marketing_leads_upsert_index.sql');
    await db.exec(`begin; ${migration} commit;`);
    assert.equal((await db.query(insert, ['meta-1', 'Fixture'])).rows.length, 1);
    await db.exec(`update public.marketing_leads set status='contacted',notes='Keep operator note' where leadgen_id='meta-1'`);
    const before = (await db.query(`select * from public.marketing_leads where leadgen_id='meta-1'`)).rows[0];
    assert.equal((await db.query(insert, ['meta-1', 'Retry must not overwrite'])).rows.length, 0);
    assert.deepEqual((await db.query(`select * from public.marketing_leads where leadgen_id='meta-1'`)).rows[0], before);
    assert.equal((await db.query(insert, ['meta-2', 'Second lead'])).rows.length, 1);
    await db.query(insert, [null, 'Manual one']);
    await db.query(insert, [null, 'Manual two']);
    assert.equal((await db.query('select count(*)::int as n from public.marketing_leads')).rows[0].n, 4);
    await db.exec(migration); // Retry is safe and preserves rows.
    assert.equal((await db.query('select count(*)::int as n from public.marketing_leads')).rows[0].n, 4);
    assert.equal((await db.query(`select relrowsecurity from pg_class where oid='public.marketing_leads'::regclass`)).rows[0].relrowsecurity, true);
    for (const role of ['anon', 'authenticated']) {
      await db.exec(`set role ${role}`);
      await assert.rejects(db.query('select * from public.marketing_leads'), /permission denied/);
      await assert.rejects(db.query(insert, ['denied', 'Denied']), /permission denied/);
      await db.exec('reset role');
    }
    console.log('SQL PASS: reproduces 42P10, new lead, duplicate preserves operator edits, NULL IDs, rerun and client access denial');
  } finally {
    await db.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
